{"script":"() => {
  const colorElements = document.querySelectorAll('[name="chassis-color"], [data-color], [aria-label*="color"], input[type="radio"][name*="color"]');
  const colors = [];
  colorElements.forEach(el => {
    colors.push({
      tag: el.tagName,
      name: el.name,
      value: el.value,
      label: el.getAttribute('aria-label'),
      dataColor: el.getAttribute('data-color')
    });
  });
  // Also look for color names in img alt text
  const colorImages = document.querySelectorAll('img[alt*="MacBook Air"][alt*="color"]');
  const colorAlts = [];
  colorImages.forEach(img => colorAlts.push(img.alt));
  return { colors, colorAlts };
}"}

